    c.unblock(2);
    c.node(2).try_become_leader();
    c.pump(4_000);
    emit_sample(&mut c, case, "STALELEADER_AFTER", &[1, 2, 3]);

    println!(
        "CA_EVENT {{\"event\":\"RUN_END\",\"case\":\"{}\",\"delivered\":{},\"dropped_ble\":{}}}",
        case, c.delivered, c.dropped_ble
    );
}

