    c.pump(4_000);
    emit_sample(&mut c, case, "RESYNC_AFTER", &[1, 2, 3]);

    println!(
        "CA_EVENT {{\"event\":\"RUN_END\",\"case\":\"{}\",\"delivered\":{},\"dropped_ble\":{}}}",
        case, c.delivered, c.dropped_ble
