        "CA_EVENT {{\"event\":\"DRIFTTRIM_TRIM\",\"case\":\"{}\",\"node\":2,\"trim_outcome\":\"{}\",\"compacted_idx\":{},\"accepted_idx\":{},\"decided_idx\":{}}}",
        case, outcome, compacted, accepted, decided
