        let read6 = match n.read(STOPSIGN_IDX + 1) {
            Some(LogEntry::StopSign(..)) => "stop_sign",
            Some(LogEntry::Decided(_)) => "decided_entry",
            Some(LogEntry::Undecided(_)) => "undecided_entry",
